exports.Items.souldew={inherit:true,onBasePower(){},onModifySpAPriority:1,onModifySpA(spa,pokemon){if([380,381].includes(pokemon.baseSpecies.num))return this.chainModify(1.5);},onModifySpDPriority:2,onModifySpD(spd,pokemon){if([380,381].includes(pokemon.baseSpecies.num))return this.chainModify(1.5);}};
